+export interface GitHubSkillSource {
+	owner: string;
+	repo: string;
+	ref?: string;
+	/** Repository-relative directory to search for skills in. */
+	subpath?: string;
+	/** Skill to pick when the repository contains several. */
+	skill?: string;
+}
