+	rest = rest.replace(/^(www\.)?github\.com\//i, "");
+	const at = rest.lastIndexOf("@");
+	if (at > 0) {
+		skill ??= rest.slice(at + 1);
+		rest = rest.slice(0, at);
+	}
+	const segments = rest.replace(/\/+$/, "").split("/");
